def rot90(x): return [list(row) for row in zip(*x[::-1])]
def flipud(x): return x[::-1]
def fliplr(x): return [r[::-1] for r in x]
def transforms(x):
    vals={}
    y=x
    for k in range(4):
        vals[f'r{k*90}']=y
        vals[f'flipud_r{k*90}']=flipud(y)
        y=rot90(y)
    return vals
